"""Render spec/data_schema.md from src/common/schema.py (the source of truth).

usage: python tools/render_schema_doc.py [--check]
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from src.common import enums as E  # noqa: E402
from src.common.schema import ALL_TABLES  # noqa: E402

TARGET = ROOT / "spec" / "data_schema.md"


def render() -> str:
    out = ["# Data Schema", "",
           "<!-- GENERATED by tools/render_schema_doc.py from src/common/schema.py. Do not edit by hand. -->", "",
           "Every shared table: where it lives, who produces it, who consumes it and its columns.",
           "Units and conventions are in `spec/financial_model_contract.md` §0.", "",
           "*Producer* is the worktree that writes the canonical data, either the CSV or the workbook table. "
           "The *sheet owner* (`spec/ownership.toml`) builds the Excel table. These are usually the same; "
           "for example, 01-data produces `fund_holdings.csv` and 03-nav builds `tbl_Holdings_MF001` from it.", "",
           "`origin`: **stored** = in the canonical CSV · **workbook_link** = formula linking another table · "
           "**workbook_calc** = formula in this table.", "", "## Tables", ""]
    out += [f"- [{t.excel_name}](#{t.key.replace('_', '-')}) — `{t.key}`" for t in ALL_TABLES]
    out.append("")
    for t in ALL_TABLES:
        out += [f"### {t.key}", "",
                f"| | |", "|---|---|",
                f"| Excel table | `{t.excel_name}` on `{t.sheet}` |",
                f"| Canonical CSV | `{t.csv_path}` |" if t.csv_path else "| Canonical CSV | workbook only |",
                f"| Producer | {t.producer} |",
                f"| Consumers | {', '.join(t.consumers)} |",
                f"| Primary key | {', '.join(t.primary_key)} |",
                f"| Append-only | {'yes: revisions add rows, nothing is overwritten' if t.append_only else 'no'} |", ""]
        if t.notes:
            out += [t.notes, ""]
        out += ["| Column | Type | Unit | Req | Origin | Allowed values / description |", "|---|---|---|---|---|---|"]
        for c in t.columns:
            allowed = " · ".join(c.enum) if c.enum else ""
            desc = "; ".join(x for x in (allowed, c.description) if x)
            out.append(f"| `{c.name}` | {c.dtype} | {c.unit} | {'✓' if c.required else ''} | {c.origin} | {desc} |")
        out.append("")
    out += ["## Enumerations", ""]
    for enum in (E.DataStatus, E.AssetClass, E.LineRole, E.CoverageStatus, E.Sector, E.OwnershipType,
                 E.BusinessModel, E.ValuationMethod, E.Case, E.MarketPriceMode, E.FairValueMode,
                 E.CheckResult, E.PeriodType, E.AccountingBasis, E.MetricKind, E.SourceTier):
        out += [f"**{enum.__name__}**: " + " · ".join(f"`{v}`" for v in enum.values()), ""]
    return "\n".join(out)


def main(check: bool) -> int:
    text = render()
    if check:
        if not TARGET.exists() or TARGET.read_text() != text:
            print("spec/data_schema.md is stale: run python tools/render_schema_doc.py")
            return 1
        return 0
    TARGET.write_text(text)
    return 0


if __name__ == "__main__":
    sys.exit(main("--check" in sys.argv))
